  ('cm_1783771476923_u', 'cr_1783610833272', 'user', '医生说我心上长了不该长的东西，今天就要做手术把它取出来。🥺', '["/cr-uploads/2026-07-11/1783771471291.png"]', '2026-07-11T12:04:36.923105+00:00', '', '', NULL, NULL, ''),
  ('cm_1783771507282_c', 'cr_1783610833272', 'connor', '……你心上长了个加载圈？

