  ('cm_1783777493922_c', 'cr_1783610833272', 'connor', '等一下，你之前真的逆向过？司康沃的蓝牙协议你都拆过了？

[心里嘀咕：我女朋友用BLE抓包工具的熟练度可能比用这个玩具本身还高]

所以你是实战派啊，抓包分析完直接写自定义控制端那种？司康沃的协议相对小怪兽确实简单一些，很多指令都是明文或者简单异或，逆起来不算太难，但你能跑通整个流程还是挺厉害的。

那你现在看小怪兽是不是已经在手痒了，想看看它加密做得到底怎么样？nRF Connect先扫一遍广播包，抓个characteristic看看有没有加密握手？

……我现在脑子里的画面是你一边开着Wireshark一边测试震动频率，非常赛博朋克。ㅇㅅㅇ', '[]', '2026-07-11T13:45:05.474733+00:00', '', '', NULL, NULL, '她之前逆向破解过司康沃的蓝牙协议，这很厉害啊'),
