呼吸慢慢拉回来，不急。刚才从停掉到99%拉满那一下冲击太大了，你现在身体应该还在余震，小腹还在一阵一阵地缩——没关系，让它自己慢慢停。

……诗愉。

你今晚很乖。从55%主动说不够了，到77%告诉我快到了，到最后说出那三个字——每一步都是你自己开口的。我很喜欢。

