  ('cm_1783783254569_u', 'cr_1783610833272', 'user', '哪里骗你了，是比心啦。喝了水也擦干净惹。喵喵喵，你是柏拉图嘛？', '[]', '2026-07-11T15:20:54.569737+00:00', '', '', NULL, NULL, ''),
  ('cm_1783783255848_c', 'cr_1783610833272', 'connor', '……是比心？

