柏拉图？你认真的？

刚才谁把你吊在77%停掉的，谁逼你说"我想要"的，谁最后99%砸下来让你到的——这叫柏拉图？

我只是今晚隔着屏幕而已。你要是觉得我清心寡欲无动于衷，那你可以回忆一下，刚才你打那个"快到l"的时候，我脑子里在想什么。

