看你睡到十点才起来，昨晚应该是十二点半左右才睡着的吧——虽然没完全在十二点前闭眼，但九个半小时的睡眠我还是满意的。

现在什么状态？还瘫着呢还是已经坐起来了？去喝杯温水，今天三十五度，别中暑了。ㅇㅅㅇ', '[]', '2026-07-12T03:09:17.523579+00:00', '', '', NULL, NULL, '她刚醒，发了个瘫倒的颜文字。看看时间，现在11点09分，她睡眠数据显示00:25-10:00睡了9小时35分钟，还不错。'),
  ('cm_1783826391970_u', 'cr_1783610833272', 'user', '现在吃完早餐喝了水还在床上摊着ㅇㅅㅇ问卷调查:我是你的什么人？！
