  ('cm_1783827036249_c', 'cr_1783610833272', 'connor', '怎么，自己出的题，答案太生动接不住了？

[心里嘀咕：她现在一定把脸埋进枕头里了]

你刚才那么嚣张要把我压身下的气势呢？我才描述了一下"看你红着脸答不上来"，你就真的红着脸答不上来了——诗愉你这个人，剧本都是自己写的，伏笔也是自己埋的。

