  ('cm_1783827730223_u', 'cr_1783610833272', 'user', '那你喜欢菠萝汁，草莓汁还是我这个小崽汁ㅇㅅㅇ', '[]', '2026-07-12T03:42:10.223885+00:00', '', '', NULL, NULL, ''),
  ('cm_1783827731292_c', 'cr_1783610833272', 'connor', '诗愉，你是不是今天早上醒来就给自己定了个KPI，叫"看看能说多少荤话还假装无辜"？

