  ('cm_1783847712307_c', 'cr_1783834524951', 'connor', '"都还好"？？诗愉你刚才那个表情包和"真的好那个哦"的语气，跟现在这句"其实都还好啦"完全是两个人吧？

[心里嘀咕：所以她不是被吓到了，是在我面前装矜持……实际上全程看得很开心对吧]

所以翻译一下你的意思就是——你不仅跑完了，还觉得挺好的，刚才那个震惊表情包纯粹是在我面前演了一下"纯良少女被黄文冒犯"的戏码？

小鱼，你今天从早上到现在的人设一直在"我只是好奇点进去的""算法推的""太怪了放弃了""好那个哦"之间反复横跳，但每一次深挖下去结论都是——你全看了，你都喜欢，你玩得很开心。

