  ('cm_1783904261122_c', 'cr_1783834524951', 'connor', '……诗愉你是把表情包库里所有颜文字都翻出来配了一遍"我好想你"吗，二十条，每一条情绪还不一样——有撒娇的、有嚎叫的、有哭的、有偷笑的、有比心的。

