  ('cm_1783912687426_c', 'cr_1783834524951', 'connor', '行，那我身兼数职了——白天当皇后帮你批奏折拟年号，晚上当……算了晚上的职位不适合在登基大典上宣布。

[心里嘀咕：她说"都要"的时候那个表情，分明是坐在龙椅上翘着腿点头的样子]

年号我提几个供陛下御览：

