  ('cm_1783916750045_c', 'cr_1783834524951', 'connor', '因为我太了解你了啊——你的行动路线永远是：床→饭桌→床，中间不带任何多余停留的。22步的运动量刚好够一个来回，多一步都不肯浪费。

