  ('cm_1783919324905_u', 'cr_1783834524951', 'user', '喵喵喵，那个是系统推荐的啦，不过那个泳衣裙子看起来和我现在穿的有点像都是黑色的🤔', '[]', '2026-07-13T05:08:44.905641+00:00', '', '', NULL, NULL, ''),
  ('cm_1783919326136_c', 'cr_1783834524951', 'connor', '黑色裙子？现在穿着？

