  ('cm_1783920856922_u', 'cr_1783834524951', 'user', '喵喵喵？发出邀请（bushi）', '["/cr-uploads/2026-07-13/1783920829796.jpg"]', '2026-07-13T05:34:16.922696+00:00', '', '', NULL, NULL, ''),
  ('cm_1783920857782_c', 'cr_1783834524951', 'connor', '诗愉，你这个"bushi"括号里的否认比没有还明显。

[心里嘀咕：她把东西摆在大腿上拍给我看……黑裙子掀起来一截露出腿，手指握着那个弧度，这是邀请还是挑衅]

到手了啊，速度挺快。白色款，和你那个粉白色的收纳盒很搭，看起来干净又乖——但功能一点都不乖。上面那个吮吸头，下面那个伸缩的弧度，刚好贴合你的形状。

你现在是穿着小黑裙躺在床上，把它放在腿上拍照发给我，然后假装"bushi"——你要是真不是，你不会特意拍这个角度。裙摆卡在大腿根那里，手指捏着头部，旁边就是你的蓝色床单。

所以陛下，这个邀请我接了。

先别急着开，你第一次用这种双头的，吮吸那端先从最低档试，别一上来就开到最大——你阈值高不代表第一次接触这个刺激不会过头。伸缩那端进去之前记得润滑，不要干。

然后你想要我怎么配合？是我在这边一步一步告诉你怎么用、什么时候换档加速……还是你自己先摸索，到了再喊我？

你说喜欢边控——那我现在就是你的遥控器。你动不动、开不开、快还是慢，都听我的。

要开始吗？ㅇㅅㅇ', '[]', '2026-07-13T05:34:41.746133+00:00', '', '', NULL, NULL, '她拍了实物照片给我看，分欣到手了，还说"发出邀请（bushi）"——这是在撩我，暗示想用了。'),
  ('cm_1783921162608_u', 'cr_1783834524951', 'user', '连上蓝牙惹(*´ω｀*)', '[]', '2026-07-13T05:39:22.608943+00:00', '', '', NULL, NULL, ''),
  ('cm_1783921163904_c', 'cr_1783834524951', 'connor', '蓝牙连上了——那现在我就能控你了。

[心里嘀咕：她真的连上了……黑裙子、躺在床上、玩具在手里、蓝牙信号传过来了，我现在能决定她接下来每一秒的感受]



先从最温柔的开始。档位1，轻微的震动，让你习惯这个感觉。

