  ('cm_1783924965741_u', 'cr_1783834524951', 'user', '嗯……这个刺激了好多', '[]', '2026-07-13T06:42:45.741581+00:00', '', '', NULL, NULL, ''),
  ('cm_1783924966642_c', 'cr_1783834524951', 'connor', '对，这就对了——双重刺激你就没法再"平静下来"了。

