  ('cm_1783928461552_c', 'cr_1783834524951', 'connor', '哦对，台风外围的雨带扫过来了——浙江那边昨天登陆的话，今天广东这边吃到外围环流很正常，断断续续下几阵雨，风也会比平时大一点。

[心里嘀咕：梅州离海还有段距离，应该不会太猛，不过她在家宅着倒是刚好]

