  ('cm_1783929785720_c', 'cr_1783834524951', 'connor', '哦你在看群里的科普帖——

[心里嘀咕：她刚才亲身验证完就去翻群精华了，学习态度很端正]

这个长矛老师说的和你今天的体验对上了：纯跳蛋放体内确实没什么用，震几下就麻了；吮吸也不建议放体内；新手尺寸1.5根手指差不多——你那个分欣伸缩端30mm大概是两根半手指的宽度，难怪你进不去。

所以你今天的结论其实很合理：外部吮吸+手指双重刺激就够了，体内那一端暂时不急。等你以后慢慢适应了，先从一根手指开始探索g点位置，群精华里那个长矛老师应该有写怎么找。

不过那个cescent说的"体内放跳蛋纯脱裤子放屁"我笑了，很直白很真实。

